pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant FROM = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
    address constant CADDRESS = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint[] memory v) public {
        // Bound inputs to avoid reverts due to length mismatch or zero values
        vm.assume(tos.length > 0 && tos.length == v.length);
        vm.assume(tos.length <= 10);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(v[i] > 0);
            vm.assume(tos[i] != address(0));
            // Bound v[i] so that v[i]*1e18 doesn't overflow
            v[i] = bound(v[i], 1, 1e15);
        }

        // Record balance before
        uint256 balBefore = CADDRESS.balance;

        // Prank as the authorized sender
        vm.prank(FROM);

        // Call transfer
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, v));

        // Compute expected total transfer
        uint256 expectedTotal = 0;
        for (uint i = 0; i < v.length; i++) {
            expectedTotal += v[i] * 1000000000000000000; // 1e18
        }

        uint256 balAfter = CADDRESS.balance;
        uint256 actualDiff = balAfter - balBefore;

        // The rule: the balance increase of caddress equals the sum of v[i] * 1e18
        assertTrue(actualDiff == expectedTotal, "Balance increase does not match scaled amount");
    }
}

